Ext.define('BNK.view.HumanResource.hrd.HrdCrsAply02MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HrdCrsAply02MViewController',

    config: {
        parentView: null,
        viewId: 'HrdCrsAply02M'
    },

    /* 조회 (신청자) */
    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.detailGrid,
            store = vm.storeInfo.Store,
            data = vm.get('detail');

        // // 페이지 초기화
        // store.getProxy().extraParams.page = 1;
        // var toolbar = refs.grid.getPlugins()[0];
        // toolbar.setCurrentPage(1);

        var sttnAplStcds = [];
        sttnAplStcds.push(Constants.sttnAplStcd.APPLY);
        sttnAplStcds.push(Constants.sttnAplStcd.PROCEEDING);
        sttnAplStcds.push(Constants.sttnAplStcd.COMPLETED);
        //PARAM SET
        var params = {
            hrHrdmStnCrsId : data.hrHrdmStnCrsId,
            stcd : Constants.stcd.NORMAL,
            sttnAplStcds : sttnAplStcds,
        //     noPaging : 'noPaging'
        };

        store.getProxy().extraParams = params;
        store.removeAll();
        store.loadPage(1);
    },

    /* 신청 전 유효성 검사 */
    validateOnApply: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            D = new Ext.Deferred(),
            record = vm.get('detail');		//연수과정신청 데이터

        var param = {
            hrHrpmCompId : SecurityUtils.getPrincipal().hrHrpmCompId,
            hrHrpmEmpId : SecurityUtils.getPrincipal().hrHrpmEmpId,
            hrHrdcStnCrsId : record.hrHrdcStnCrsId,
        };

        //동일과목신청한 적이 있는지 확인한다.
        Ext.Ajax.request({
            headers : {
                serviceId : 'HrdCrsSvc.findDupHrdCrsWithAply',
                viewId : me.getViewId(),
                scope : me
            },
            jsonData : param,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                if (res.dupHrdCrsCmp.length < 1) { //중복신청된 게 없다면 다음 로직으로
                    D.resolve(true);
                    return;
                }

                var dts = '';
                for ( var i in res.dupHrdCrsCmp) {
                    var dupHrdCrsCmp = res.dupHrdCrsCmp[i];
                    var strdtFmt = DateUtils.parseDate(dupHrdCrsCmp.sttnStrdt);
                    var edtFmt = DateUtils.parseDate(dupHrdCrsCmp.sttnEdt);

                    if (dts.length == 0) {
                        dts = Ext.String.format('{0}~{1}', strdtFmt, edtFmt);
                        continue;
                    }

                    dts += ', ' + Ext.String.format('{0}~{1}', strdtFmt, edtFmt);
                }
                var errMsg = Ext.String.format('동일한 과정을 이수한 적이 있어,<br />재수강 시 점수 반영이 되지 않을 수 있습니다.<br />계속 하시겠습니까?<br /><br />(수료한 연수기간: {0})', dts);

                Ext.Msg.confirm('확인', errMsg, function(btn) {
                    switch (btn) {
                        case 'yes':
                            D.resolve(true);
                            break;
                        default:
                            D.reject();
                            break;
                    }
                });

            },
            failure : function(res, scope) {
                D.reject();
            }
        });

        return D.promise;
    },

    fnSetDetailInfo: function(targetData) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            data = vm.get('detail'),
            keyArr = Object.keys(data),
            skipKeys = [ 'rn', 'id', 'hrHrpmCompId' ];

        for ( var j in keyArr) {
            var key = keyArr[j];
            if (skipKeys.indexOf(key) > -1) {
                continue;
            }
            targetData[key] = data[key];
        }

        return targetData;
    },

    onComplete: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var win = Ext.create('ExpNteAply51M'); // 결과 완료 팝업

        var sumScreen = win.getReferences().sumScreen;
        var message = win.getReferences().message;
        sumScreen.setVisibility(false);
        message.setHtml("연수 신청을 완료 하였습니다");
        me.mon(win, 'destroy', function() {
            var me = this,
                //home = Ext.getCmp(Property.ROUTE_HOME),
                home = this.getView().up(Property.ROUTE_HOME),
                naviView = home.lookup('NaviView'),
                backButton = naviView.getNavigationBar().getBackButton();
            me.getParentView().controller.onBtnSearchTap();
            backButton.onTap();	// 뒤로가기
        }, me);

        win.show();
    },

    /* 결재선 버튼 클릭 이벤트 */
    onBtnAplyLineTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            win = Ext.create('BNK.view.common.ApprovalLinePopup', {});

        me.mon(win, 'selected', function(data, popup) {
            popup.close();

            vm.set('applyLine', data);
            var me = this,
                refs = me.getReferences(),
                approvalLineGrid = refs.approvalLineGrid;

            ApprovalBoxSvc.setApprovalLine({
                scope               : me,
                command             : Constants.sanction.DRAFT, // 결재선구분자 : 기안(01)
                approvalLineGrid    : approvalLineGrid,   // 결재선 그리드 객체
                approvalLineRecords : data        // 결재선선택 데이터
            });

        }, me);


        win.show();
    },

    /* 결재 버튼 클릭 이벤트 */
    onBtnAplyTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.detailGrid,
            approvalLineGrid = refs.approvalLineGrid,
            record = vm.data.detail;		//연수과정신청 데이터

            //VALIDATION AREA 20190322/20190322
            var sttnAplEdtDate = new Date(DateUtils.parseDate(record.sttnAplEdt)).setHours(0, 0, 0, 0),
            toDate = new Date().setHours(0, 0, 0, 0);
        if (sttnAplEdtDate < toDate) {
            Ext.Msg.alert('확인', Messages.getMessage('E8006', [ '신청일자가 지나서', '신청이' ]));
            /**E8006 : {0} {1} 불가능 합니다.*/
            return;
        }

        // 결재선
        if(!vm.get('applyLine')){
            Ext.Msg.alert('확인', '- 결재선을 선택해주세요');
            return;
        }
        //END VALIDATION AREA

        me.validateOnApply().then(function(validateFlag) {
            //일반 유저
            var saveData = {
                cmgrpCd : Property.CMGRP_CD,
                sysCd : Property.SYS_CD,
                stcd : Constants.stcd.NORMAL,
                hrHrpmCompId : SecurityUtils.getPrincipal().hrHrpmCompId,
                hrHrpmEmpId : SecurityUtils.getPrincipal().hrHrpmEmpId,
                dpnm : SecurityUtils.getPrincipal().dpnm,
                empeNm : SecurityUtils.getPrincipal().userNm,
                sttnAplDt : DateUtils.getDate(new Date()), //2019.03.26. 신청일자는 결재일자가 아닌, 기안 올린 신청한 당일로 들어가야 함.  added by ha.cheon
            };
            var newRecord = me.fnSetDetailInfo(saveData);
            newRecord.rn = 1;

            var afterchange = [];
            afterchange.push(newRecord);
            //GO SANCTION POPUP	 (신청)
            ApprovalBoxSvc.draft({
                scope                 : me,
                edocCd                : 'HrdCrsAply71',				 	 		// 전자문서관리에서 설정된 문서코드: 화면ID를 사용함
                docNm                 : '연수신청서', 							 		// 문서명
                bizDvcd               : 'HRD', 							 		// 업무구분코드
                bizServiceId          : 'HrdCrsSvc.saveHrdCrsInfo',   			// 연관 업무서비스ID
                aprHistId             : null,						 	 		// 결재이력ID
                approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), 	// 결재선 그리드 데이터
                docData               : {								 		// 결재문서 데이터
                    fieldValues       : vm.get('fieldValues'),
                    beforechange      : [],
                    afterchange       : afterchange 			 				// 결재문서 필드값
                }
            });
        });
    },

    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            initConfig = component.config,
            data = initConfig.records[0].data,
            grid = refs.detailGrid,
            store = grid.getStore();

        me.setParentView(component.parentView);		// 부모 창
        vm.set('detail', data);
        vm.set('detail.id', Ext.id());
        vm.set('detail.crud', 'C');

        ApprovalBoxSvc.setup({
            command   : Constants.sanction.DRAFT,
            viewModel : vm,
            edocCd    : 'HrdCrsAply71',
            scope     : me
        });

        grid.el.select('.x-headercontainer').setStyle('height',	'0px');

        me.onSelect();
    },

    onJsonstoreLoad: function(store, records, successful, operation, eOpts) {
        var me = this,
            refs = me.getReferences();

        for(var i in records) {
            if (records[i].data.hrHrpmEmpId == SecurityUtils.getPrincipal().hrHrpmEmpId) {
                refs.gridToolbar.setHtml('신청자 (본인신청완료)');
            }
        }
    }

});